namespace sv_5c3ba984fbfd4f84bc9a327196fcb88a.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_5c3ba984fbfd4f84bc9a327196fcb88a.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <!-- Left Sidebar -->
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        @if (categories is not null)
        {
            <div class="filter-section">
                <h4>Categories</h4>
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                        @category
                    </label>
                }
            </div>
        }

        <div class="filter-section">
            <h4>Price Range</h4>
            <div class="price-inputs">
                <input type="number" placeholder="Min" @bind="minPrice" min="0" step="0.01" />
                <span>–</span>
                <input type="number" placeholder="Max" @bind="maxPrice" min="0" step="0.01" />
            </div>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="inStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    <!-- Main Content -->
    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="loading-indicator">
                <p>Loading products...</p>
            </div>
        }
        else if (searchResult is null || searchResult.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <!-- Toolbar -->
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="results-info">
                    Showing @(((searchResult.Page - 1) * searchResult.PageSize) + 1)–@(Math.Min(searchResult.Page * searchResult.PageSize, searchResult.TotalCount)) of @searchResult.TotalCount products
                </span>
            </div>

            <!-- Product Grid -->
            <div class="product-grid">
                @foreach (var product in searchResult.Items)
                {
                    <div class="product-card" @onclick="() => OnProductSelected(product)">
                        <div class="product-image" title="@product.Name">
                            <span>@product.Name</span>
                        </div>
                        <div class="product-info">
                            <h5 class="product-name">@product.Name</h5>
                            <p class="product-price">@product.Price.ToString("C")</p>
                            <div class="product-rating">@GetStarRating(product.Rating)</div>
                            @if (!product.InStock)
                            {
                                <span class="badge-out-of-stock">Out of Stock</span>
                            }
                            <button class="btn btn-cart"
                                    disabled="@(!product.InStock)"
                                    @onclick="() => AddToCart(product)"
                                    @onclick:stopPropagation="true">
                                Add to Cart
                            </button>
                        </div>
                    </div>
                }
            </div>

            <!-- Pagination -->
            <nav class="pagination-controls">
                <button class="btn btn-page" disabled="@(currentPage <= 1)" @onclick="PreviousPage">Previous</button>
                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn btn-page @(pageNum == currentPage ? "active" : "")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }
                <button class="btn btn-page" disabled="@(currentPage >= totalPages)" @onclick="NextPage">Next</button>
            </nav>
        }
    </main>
</div>

<style>
    .catalog-container {
        display: flex;
        gap: 1.5rem;
        padding: 1rem;
    }

    .catalog-sidebar {
        width: 25%;
        min-width: 220px;
        border-right: 1px solid #ddd;
        padding-right: 1.5rem;
    }

    .catalog-main {
        width: 75%;
        flex: 1;
    }

    .filter-section {
        margin-bottom: 1.25rem;
    }

    .filter-section h4 {
        margin-bottom: 0.5rem;
        font-size: 0.95rem;
    }

    .filter-checkbox {
        display: flex;
        align-items: center;
        gap: 0.4rem;
        margin-bottom: 0.35rem;
        cursor: pointer;
    }

    .price-inputs {
        display: flex;
        align-items: center;
        gap: 0.5rem;
    }

    .price-inputs input {
        width: 80px;
        padding: 0.3rem 0.5rem;
        border: 1px solid #ccc;
        border-radius: 4px;
    }

    .filter-actions {
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
        margin-top: 1rem;
    }

    .btn {
        padding: 0.5rem 1rem;
        border: none;
        border-radius: 4px;
        cursor: pointer;
        font-size: 0.9rem;
    }

    .btn-primary {
        background-color: #0d6efd;
        color: white;
    }

    .btn-primary:hover {
        background-color: #0b5ed7;
    }

    .btn-secondary {
        background-color: #6c757d;
        color: white;
    }

    .btn-secondary:hover {
        background-color: #5c636a;
    }

    .catalog-toolbar {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 1rem;
        padding: 0.75rem;
        background: #f8f9fa;
        border-radius: 4px;
    }

    .sort-control {
        display: flex;
        align-items: center;
        gap: 0.5rem;
    }

    .sort-control select {
        padding: 0.35rem 0.5rem;
        border: 1px solid #ccc;
        border-radius: 4px;
    }

    .results-info {
        font-size: 0.9rem;
        color: #666;
    }

    .product-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
        gap: 1.25rem;
    }

    .product-card {
        border: 1px solid #ddd;
        border-radius: 8px;
        overflow: hidden;
        cursor: pointer;
        transition: box-shadow 0.2s;
    }

    .product-card:hover {
        box-shadow: 0 2px 12px rgba(0,0,0,0.12);
    }

    .product-image {
        background: #e9ecef;
        height: 160px;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #666;
        font-size: 0.85rem;
        text-align: center;
        padding: 0.5rem;
    }

    .product-info {
        padding: 0.75rem;
    }

    .product-name {
        margin: 0 0 0.3rem;
        font-size: 1rem;
    }

    .product-price {
        font-weight: bold;
        color: #198754;
        margin: 0 0 0.3rem;
    }

    .product-rating {
        color: #ffc107;
        margin-bottom: 0.4rem;
    }

    .badge-out-of-stock {
        display: inline-block;
        background: #dc3545;
        color: white;
        font-size: 0.75rem;
        padding: 0.2rem 0.5rem;
        border-radius: 3px;
        margin-bottom: 0.4rem;
    }

    .btn-cart {
        width: 100%;
        background-color: #198754;
        color: white;
        margin-top: 0.5rem;
    }

    .btn-cart:hover:not(:disabled) {
        background-color: #157347;
    }

    .btn-cart:disabled {
        background-color: #ccc;
        cursor: not-allowed;
    }

    .pagination-controls {
        display: flex;
        justify-content: center;
        gap: 0.4rem;
        margin-top: 1.5rem;
    }

    .btn-page {
        background: #fff;
        border: 1px solid #ddd;
        min-width: 38px;
    }

    .btn-page:hover:not(:disabled) {
        background: #e9ecef;
    }

    .btn-page.active {
        background-color: #0d6efd;
        color: white;
        border-color: #0d6efd;
    }

    .btn-page:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }

    .loading-indicator, .empty-state {
        text-align: center;
        padding: 3rem 1rem;
        color: #666;
    }

    .alert-danger {
        background: #f8d7da;
        color: #842029;
        border: 1px solid #f5c2c7;
        border-radius: 4px;
        padding: 1rem;
    }
</style>

@code {
    [Parameter] public EventCallback<Product> OnProductClicked { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalPages;
    private bool isLoading = true;
    private string? errorMessage;
    private PagedResult<Product>? searchResult;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = LoadProducts();
            categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;
        StateHasChanged();

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            searchResult = await ProductService.SearchAsync(filter, sortBy, currentPage, pageSize);
            totalPages = (int)Math.Ceiling((double)searchResult.TotalCount / pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await LoadProducts();
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task PreviousPage() => await GoToPage(currentPage - 1);
    private async Task NextPage() => await GoToPage(currentPage + 1);

    private async Task OnProductSelected(Product product)
    {
        if (OnProductClicked.HasDelegate)
            await OnProductClicked.InvokeAsync(product);
    }

    private void AddToCart(Product product)
    {
        // Placeholder for cart functionality
    }

    private string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

